macro_rules! deps {
    () => {
        TransformTyOptions!();
    };
}

macro_rules! transform_instance {
    () => {
        deps!();
        # [doc = " Transforms an instance for LLVM CFI and cross-language LLVM CFI support using Itanium C++ ABI"] # [doc = " mangling."] # [doc = ""] # [doc = " typeid_for_instance is called at two locations, initially when declaring/defining functions and"] # [doc = " methods, and later during code generation at call sites, after type erasure might have occurred."] # [doc = ""] # [doc = " In the first call (i.e., when declaring/defining functions and methods), it encodes type ids for"] # [doc = " an FnAbi or Instance, and these type ids are attached to functions and methods. (These type ids"] # [doc = " are used later by the LowerTypeTests LLVM pass to aggregate functions in groups derived from"] # [doc = " these type ids.)"] # [doc = ""] # [doc = " In the second call (i.e., during code generation at call sites), it encodes a type id for an"] # [doc = " FnAbi or Instance, after type erasure might have occurred, and this type id is used for testing"] # [doc = " if a function is member of the group derived from this type id. Therefore, in the first call to"] # [doc = " typeid_for_fnabi (when type ids are attached to functions and methods), it can only include at"] # [doc = " most as much information that would be available in the second call (i.e., during code"] # [doc = " generation at call sites); otherwise, the type ids would not match."] # [doc = ""] # [doc = " For this, it:"] # [doc = ""] # [doc = " * Adjust the type ids of DropGlues (see below)."] # [doc = " * Adjusts the type ids of VTableShims to the type id expected in the call sites for the"] # [doc = "   entry in the vtable (i.e., by using the signature of the closure passed as an argument to the"] # [doc = "   shim, or by just removing self)."] # [doc = " * Performs type erasure for calls on trait objects by transforming self into a trait object of"] # [doc = "   the trait that defines the method."] # [doc = " * Performs type erasure for closures call methods by transforming self into a trait object of"] # [doc = "   the Fn trait that defines the method (for being attached as a secondary type id)."] # [doc = ""] # [instrument (level = "trace" , skip (tcx))] pub (crate) fn transform_instance < 'tcx > (tcx : TyCtxt < 'tcx > , mut instance : Instance < 'tcx > , options : TransformTyOptions ,) -> Instance < 'tcx > { if (matches ! (instance . def , ty :: InstanceKind :: Virtual (..)) && tcx . is_lang_item (instance . def_id () , LangItem :: DropInPlace)) || matches ! (instance . def , ty :: InstanceKind :: DropGlue (..)) { let def_id = tcx . lang_items () . drop_trait () . unwrap_or_else (| | bug ! ("typeid_for_instance: couldn't get drop_trait lang item")) ; let predicate = ty :: ExistentialPredicate :: Trait (ty :: ExistentialTraitRef :: new_from_args (tcx , def_id , ty :: List :: empty () ,)) ; let predicates = tcx . mk_poly_existential_predicates (& [ty :: Binder :: dummy (predicate)]) ; let self_ty = Ty :: new_dynamic (tcx , predicates , tcx . lifetimes . re_erased , ty :: Dyn) ; instance . args = tcx . mk_args_trait (self_ty , List :: empty ()) ; } else if let ty :: InstanceKind :: Virtual (def_id , _) = instance . def { let upcast_ty = match tcx . trait_of_assoc (def_id) { Some (trait_id) => trait_object_ty (tcx , ty :: Binder :: dummy (ty :: TraitRef :: from_assoc (tcx , trait_id , instance . args)) ,) , None => instance . args . type_at (0) , } ; let ty :: Dynamic (preds , lifetime , kind) = upcast_ty . kind () else { bug ! ("Tried to remove autotraits from non-dynamic type {upcast_ty}") ; } ; let self_ty = if preds . principal () . is_some () { let filtered_preds = tcx . mk_poly_existential_predicates_from_iter (preds . into_iter () . filter (| pred | { ! matches ! (pred . skip_binder () , ty :: ExistentialPredicate :: AutoTrait (..)) })) ; Ty :: new_dynamic (tcx , filtered_preds , * lifetime , * kind) } else { tcx . types . unit } ; instance . args = tcx . mk_args_trait (self_ty , instance . args . into_iter () . skip (1)) ; } else if let ty :: InstanceKind :: VTableShim (def_id) = instance . def && let Some (trait_id) = tcx . trait_of_assoc (def_id) { let trait_ref = ty :: TraitRef :: new_from_args (tcx , trait_id , instance . args) ; let invoke_ty = trait_object_ty (tcx , ty :: Binder :: dummy (trait_ref)) ; instance . args = tcx . mk_args_trait (invoke_ty , trait_ref . args . into_iter () . skip (1)) ; } if ! options . contains (TransformTyOptions :: USE_CONCRETE_SELF) { if let Some ((trait_ref , method_id , ancestor)) = implemented_method (tcx , instance) { let trait_ref = tcx . instantiate_and_normalize_erasing_regions (instance . args , ty :: TypingEnv :: fully_monomorphized () , trait_ref ,) ; let invoke_ty = trait_object_ty (tcx , ty :: Binder :: dummy (trait_ref)) ; instance . def = ty :: InstanceKind :: Virtual (method_id , 0) ; let abstract_trait_args = tcx . mk_args_trait (invoke_ty , trait_ref . args . into_iter () . skip (1)) ; instance . args = instance . args . rebase_onto (tcx , ancestor , abstract_trait_args) ; } else if tcx . is_closure_like (instance . def_id ()) { let closure_ty = instance . ty (tcx , ty :: TypingEnv :: fully_monomorphized ()) ; let (trait_id , inputs) = match closure_ty . kind () { ty :: Closure (..) => { let closure_args = instance . args . as_closure () ; let trait_id = tcx . fn_trait_kind_to_def_id (closure_args . kind ()) . unwrap () ; let tuple_args = tcx . instantiate_bound_regions_with_erased (closure_args . sig ()) . inputs () [0] ; (trait_id , Some (tuple_args)) } ty :: Coroutine (..) => match tcx . coroutine_kind (instance . def_id ()) . unwrap () { hir :: CoroutineKind :: Coroutine (..) => (tcx . require_lang_item (LangItem :: Coroutine , DUMMY_SP) , Some (instance . args . as_coroutine () . resume_ty ()) ,) , hir :: CoroutineKind :: Desugared (desugaring , _) => { let lang_item = match desugaring { hir :: CoroutineDesugaring :: Async => LangItem :: Future , hir :: CoroutineDesugaring :: AsyncGen => LangItem :: AsyncIterator , hir :: CoroutineDesugaring :: Gen => LangItem :: Iterator , } ; (tcx . require_lang_item (lang_item , DUMMY_SP) , None) } } , ty :: CoroutineClosure (..) => (tcx . require_lang_item (LangItem :: FnOnce , DUMMY_SP) , Some (tcx . instantiate_bound_regions_with_erased (instance . args . as_coroutine_closure () . coroutine_closure_sig () ,) . tupled_inputs_ty ,) ,) , x => bug ! ("Unexpected type kind for closure-like: {x:?}") , } ; let concrete_args = tcx . mk_args_trait (closure_ty , inputs . map (Into :: into)) ; let trait_ref = ty :: TraitRef :: new_from_args (tcx , trait_id , concrete_args) ; let invoke_ty = trait_object_ty (tcx , ty :: Binder :: dummy (trait_ref)) ; let abstract_args = tcx . mk_args_trait (invoke_ty , trait_ref . args . into_iter () . skip (1)) ; let call = tcx . associated_items (trait_id) . in_definition_order () . find (| it | it . is_fn ()) . expect ("No call-family function on closure-like Fn trait?") . def_id ; instance . def = ty :: InstanceKind :: Virtual (call , 0) ; instance . args = abstract_args ; } } instance }
    };
}

transform_instance!();